"use client";

import {useEffect,useMemo,useState} from "react";
import {supabase} from "./supabase-client";
import "./history.css";
import "./workflow.css";

type CartItem={id:string|number;name:string;price:number;qty:number;emoji:string;organization_id?:string;image_url?:string;presentation?:string;unit_measure?:string;unit_quantity?:number};
type CatalogProduct={id:string|number;organization_id?:string;name:string;sku?:string;price:number;category:string;description?:string;desc?:string;image_url?:string;unit_measure?:string;unit_quantity?:number;stock?:number;average_cost?:number;is_active?:boolean;emoji?:string;tag?:string};
type Profile={id:string;email:string;full_name:string|null;platform_role:string;must_change_password?:boolean;username?:string|null};
type Org={id:string;name:string;status:string;slug?:string;owner_user_id?:string};
type Employee={member_id:string;user_id:string;full_name:string;phone:string;email:string;username:string;membership_type:string;role_code:string;role_name:string;status:string;must_change_password:boolean;created_at:string};
type PermissionSetting={permission_code:string;permission_name:string;module:string;enabled:boolean;role_default:boolean;is_override:boolean};
type CreditSale={id:string;customer_name:string;total:number;paid_amount:number;balance:number;status:string;due_date?:string;created_at:string};
type SubscriptionPayment={id:string;amount:number;status:string;method:string;period_label:string;paid_at:string};
type ProviderApplication={id:string;business_name:string;tax_id:string;contact_name:string;phone:string;city:string;address:string;status:string;created_at:string};
type Order={id:string;organization_id?:string;order_number:number;organization_name?:string;status:string;payment_method:string;payment_status?:string;total:number;commission_amount:number;shared_cash_amount?:number;shared_card_amount?:number;shared_credit_amount?:number;customer_data_unlocked?:boolean;customer_name:string;customer_phone?:string;delivery_address?:string;delivery_city?:string;notes?:string;created_at:string;updated_at?:string;delivered_at?:string;cancelled_at?:string;commission_refund_due_at?:string;commission_refunded_at?:string};
type TrackingResult={order_number:number;status:string;payment_method:string;total:number;organization_name:string;created_at:string;updated_at:string};
type NewOrderSummary={number:number;phone:string;address:string;city:string};
type ExpenseConcept={id:string;name:string;is_active:boolean};
type PurchaseRecord={id:string;purchase_date:string;supplier_id?:string;supplier?:string;invoice_number?:string;total:number;paid_amount:number;due_date?:string;payment_method:string;payment_status:string;payment_note?:string;created_at:string};
