type FinancialSummary={total_sales:number;cash_sales:number;transfer_sales:number;credit_sales:number;cost_of_sales:number;expenses:number;purchases:number;gross_profit:number;net_profit:number;accounts_payable?:number;purchase_payments?:number};
type BusinessSupplier={id:string;name:string;tax_id?:string;contact_name?:string;phone?:string;email?:string;payment_terms_days:number;is_active:boolean};
type SupplierPayment={id:string;purchase_id:string;amount:number;method:string;payment_date:string;reference?:string;note?:string;created_at:string;inventory_purchases?:{supplier?:string;invoice_number?:string}|null};
type CashFlowBalance={cash_sales:number;transfer_sales:number;credit_receipts:number;cash_inflow:number;supplier_outflow:number;expense_outflow:number;cash_outflow:number;net_cash_flow:number;accounts_receivable:number;expected_cash:number;inventory_value:number;accounts_payable:number;net_position:number};

const products=[
 {id:1,name:"Canasta campesina",desc:"Frutas y verduras frescas",price:48900,emoji:"🥬",tag:"Más vendido",category:"Frutas y verduras"},
 {id:2,name:"Huevos de campo x30",desc:"Gallinas libres de jaula",price:21500,emoji:"🥚",tag:"Fresco",category:"Huevos y lácteos"},
 {id:3,name:"Aguacate Hass x1 kg",desc:"Seleccionado en origen",price:12900,emoji:"🥑",tag:"Oferta",category:"Frutas y verduras"},
 {id:4,name:"Café especial 500 g",desc:"Origen colombiano",price:27900,emoji:"☕",tag:"Premium",category:"Despensa"},
 {id:5,name:"Carne de res 1 kg",desc:"Corte fresco seleccionado",price:35900,emoji:"🥩",tag:"Nuevo",category:"Carnes"},
 {id:6,name:"Leche campesina 1 L",desc:"Pasteurizada y refrigerada",price:6900,emoji:"🥛",tag:"Local",category:"Huevos y lácteos"},
];
const statusLabel:Record<string,string>={pending_confirmation:"Pte. confirmar",orders:"Pedido confirmado",confirmed:"Confirmado",preparing:"En preparación",dispatched:"En despacho",out_for_delivery:"En ruta",delivered:"Entregado",returned:"Devuelto",cancelled:"Cancelado"};
const orderQueue=(status:string)=>["pending_confirmation","returned"].includes(status)?"pending_confirmation":["orders","confirmed"].includes(status)?"orders":status;
const money=(n:number)=>new Intl.NumberFormat("es-CO",{style:"currency",currency:"COP",maximumFractionDigits:0}).format(n);
