 async function saveAddress(){if(!selected||!address.delivery_address)return;setLoading(true);const {error}=await supabase.rpc("update_order_delivery_details",{target_order:selected.id,new_address:address.delivery_address,new_city:address.delivery_city,new_notes:address.notes});setLoading(false);if(error)say(`No se pudo guardar: ${error.message}`);else{say("Datos de entrega actualizados.");setDialog(null);refresh?.()}}
