 if(profile)return <main className="access-page"><section className="access-card"><span className="kicker">ACCESO ADMINISTRATIVO</span><h1>Bienvenido, {profile.full_name||profile.email}</h1><p>{profile.platform_role==="super_admin"?<>GoMarket reconoció tu cuenta como <b>superadministrador</b>.</>:hasBusiness?<>GoMarket reconoció tu empresa aprobada y tu acceso como <b>proveedor</b>.</>:"Esta cuenta todavía no tiene un negocio vinculado."}</p>{profile.platform_role!=="super_admin"&&!hasBusiness&&<p>Completa el registro de la empresa para enviarla a aprobación.</p>}<button className="primary wide" onClick={onReady}>{profile.platform_role!=="super_admin"&&!hasBusiness?"Registrar mi negocio":"Abrir mi panel"}</button><button className="text-button" onClick={signOut}>Cerrar sesión</button><button className="text-button" onClick={onBack}>Volver a la tienda</button></section></main>;
